import logging
from functools import wraps


def add_function_trace(function):

    @wraps(function)
    def wrapped_function(*args, **kwargs):
        logging.debug("execute {} args={} kwargs={}".format(function.__name__, args, kwargs))
        result = function(*args, **kwargs)
        logging.debug("{} return {}".format(function.__name__, result))
        return result

    return wrapped_function
